    var today = chicagoToday();
    var y = addDaysYmd(today, -1);
    var a = map[y], b = map[today];
    if (!a || !b || typeof a !== "object" || typeof b !== "object" || a.mergedInto) return false;
    if (!shiftOpen(a) || b.splitMerged) return false;
