    readRideLog().forEach(function (e) { if (e && e.day === day) byCode[e.code || ("L" + out.length)] = Object.assign({}, byCode[e.code] || {}, e); });
    Object.keys(byCode).forEach(function (k) { out.push(byCode[k]); });
