    /* only minutes fully covered by GPS are judged (the miles of a gap arrive with the next fix); End judges the rest */
    var upTo = force ? now : Math.min(now, Number(M.gpsAt) || 0);
    var done = Math.floor((upTo - M.startedAt) / 60000);
